"""Inspect the workspace: list files and, if a SQLite DB exists, dump its schema."""
import os
import sqlite3

print("CWD:", os.getcwd())
print("--- files ---")
for root, dirs, files in os.walk("."):
    # skip hidden tooling dirs
    dirs[:] = [d for d in dirs if not d.startswith(".")]
    for name in files:
        print(os.path.join(root, name))

print("--- sqlite databases ---")
for root, dirs, files in os.walk("."):
    dirs[:] = [d for d in dirs if not d.startswith(".")]
    for name in files:
        if name.endswith((".db", ".sqlite", ".sqlite3")):
            path = os.path.join(root, name)
            print("DB:", path)
            try:
                conn = sqlite3.connect(path)
                for row in conn.execute(
                    "SELECT type, name, sql FROM sqlite_master WHERE type IN ('table','index') ORDER BY type, name"
                ):
                    print(row[0], "|", row[1], "|", row[2])
                conn.close()
            except sqlite3.Error as e:
                print("  error reading:", e)

